// Exports the event ABIs the indexer needs from the forge artifacts (contracts/out) into abis/*.ts as const.
// Run `forge build` in contracts/ first. The generated files are committed, so CI and Docker need no forge.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const out = join(here, '..', '..', 'contracts', 'out')
const dest = join(here, '..', 'abis')
mkdirSync(dest, { recursive: true })

/** artifact name, output name, optional allow list of event names (all events when omitted) */
const targets = [
  ['DepositoPoolLedger', 'DepositoPoolLedger', ['BankAdded', 'BankBalance', 'BankProfit', 'MaturityRecorded', 'ProfitRecorded', 'ReserveRecorded']],
  ['TawfDepositoSeries', 'TawfDepositoSeries', ['Subscribed', 'SubscriptionCancelled', 'Allocated', 'ProfitDistributed', 'ProfitClaimed', 'MaturitySettled', 'Redeemed', 'RatePosted']],
  [
    'SukukDistributor',
    'SukukDistributor',
    ['SubscriptionOpened', 'Subscribed', 'Issued', 'SubscriptionCancelled', 'Refunded', 'ProfitDistributed', 'ProfitClaimed', 'MaturitySettled', 'DefaultSettled', 'Redeemed', 'ReserveUpdated', 'CoinToppedUp', 'PayoutPart'],
  ],
  ['ScfInvestorLimitModule', 'ScfInvestorLimitModule', ['ProfileSet']],
  ['IdentityRegistry', 'IdentityRegistry', ['IdentityRegistered', 'IdentityRemoved']],
  ['Token', 'Token', ['Transfer', 'Paused', 'Unpaused', 'AddressFrozen', 'TokensFrozen', 'TokensUnfrozen']],
]

for (const [artifact, name, keep] of targets) {
  const json = JSON.parse(readFileSync(join(out, `${artifact}.sol`, `${artifact}.json`), 'utf8'))
  const events = json.abi.filter((e) => e.type === 'event' && (!keep || keep.includes(e.name)))
  const missing = (keep ?? []).filter((k) => !events.some((e) => e.name === k))
  if (missing.length) throw new Error(`${artifact}: missing events ${missing.join(', ')}`)
  writeFileSync(join(dest, `${name}.ts`), `// Generated by scripts/export-abis.mjs from contracts/out. Do not edit.\nexport const ${name}Abi = ${JSON.stringify(events, null, 2)} as const\n`)
  console.log(`${name}: ${events.length} events`)
}
